SELECT COUNT(*) FROM insurance_employee WHERE is_deleted = 0 AND status = 1
AND company_id IN

    #{id}

SELECT ic.id as deptId, ic.name as deptName, COUNT(ie.id) as employeeCount FROM insured_company ic LEFT JOIN insurance_employee ie ON ic.id = ie.company_id AND ie.is_deleted = 0 AND ie.status = 1 WHERE ic.is_deleted = 0 AND ic.id IN
#{id}
GROUP BY ic.id, ic.name ORDER BY employeeCount DESC

SELECT DATE_FORMAT(hire_date, '%Y-%m') as month, COUNT(*) as count FROM insurance_employee WHERE is_deleted = 0 AND hire_date IS NOT NULL AND hire_date >= DATE_SUB(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 11 MONTH) AND company_id IN
#{id}
GROUP BY DATE_FORMAT(hire_date, '%Y-%m') ORDER BY month ASC
